/** Routes tagged `hr · esocial`. */
export class HrEsocialResource extends Resource {
  /**
   * Descarta o evento.
   *
   * Só o que ainda não foi para a Receita (inválido, pronto ou recusado). O
   * assunto fica livre para gerar de novo.
   *
   * `POST /v1/hr/esocial/events/{id}/cancel`
   *
   * @param id Id do evento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  cancelEsocialEvent(id: string, body: S.HrPayrollVersionInput, options?: RequestOptions): Promise<S.HrEsocialEvent> {
    return this._http.request({ method: 'POST', path: `/v1/hr/esocial/events/${seg(id)}/cancel`, body, options });
  }

  /**
   * Lança as diferenças.
   *
   * Cada recolhimento que o governo apurou a maior vira um título
   * complementar no financeiro, com o credor e a carteira da configuração da
   * folha. Repetir é seguro: o título que já existe volta o mesmo, e o
   * recusado tenta de novo. A diferença a menor não vira título.
   *
   * `POST /v1/hr/esocial/settlements/{period}/dispatch`
   *
   * @param period `AAAA-MM`, ou `AAAA` no 13º
   * @param options Per-call overrides.
   */
  dispatchEsocialSettlement(period: string, options?: RequestOptions): Promise<S.HrEsocialSettlementDispatch> {
    return this._http.request({ method: 'POST', path: `/v1/hr/esocial/settlements/${seg(period)}/dispatch`, options });
  }

  /**
   * Pede a exclusão do evento.
   *
   * Gera o S-3000 que tira da Receita um evento de pessoa já aceito. O
   * evento segue aceito até a Receita aceitar a exclusão; aí vira `excluded`
   * e o assunto fica livre para mandar de novo, certo. A admissão só sai
   * depois de excluídos os eventos que vieram depois dela no vínculo.
   *
   * `POST /v1/hr/esocial/events/{id}/exclude`
   *
   * @param id Id do evento aceito
   * @param body Request body.
   * @param options Per-call overrides.
   */
  excludeEsocialEvent(id: string, body: S.HrPayrollVersionInput, options?: RequestOptions): Promise<S.HrEsocialEvent> {
    return this._http.request({ method: 'POST', path: `/v1/hr/esocial/events/${seg(id)}/exclude`, body, options });
  }

  /**
   * Gera os eventos que faltam.
   *
   * Um por assunto sem evento vivo. Cada um sai `ready`, assinado, ou
   * `invalid` com o que corrigir no cadastro; o laço manda os prontos.
   *
   * `POST /v1/hr/esocial/generate`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  generateEsocialEvents(body: S.HrEsocialGenerateInput, options?: RequestOptions): Promise<S.HrEsocialGenerated> {
    return this._http.request({ method: 'POST', path: `/v1/hr/esocial/generate`, body, options });
  }

  /**
   * O evento com o XML.
   *
   * O XML leva CPF, endereço, raça e dependentes: pede a gestão da folha e a
   * abertura fica na auditoria.
   *
   * `GET /v1/hr/esocial/events/{id}`
   *
   * @param id Id do evento
   * @param options Per-call overrides.
   */
  getEsocialEvent(id: string, options?: RequestOptions): Promise<S.HrEsocialEventDetail> {
    return this._http.request({ method: 'GET', path: `/v1/hr/esocial/events/${seg(id)}`, options });
  }

  /**
   * O resumo do eSocial.
   *
   * Os eventos por situação, se as tabelas já foram aceitas e quantas
   * admissões e desligamentos ainda não têm evento.
   *
   * `GET /v1/hr/esocial/overview`
   *
   * @param options Per-call overrides.
   */
  getEsocialOverview(options?: RequestOptions): Promise<S.HrEsocialOverview> {
    return this._http.request({ method: 'GET', path: `/v1/hr/esocial/overview`, options });
  }

  /**
   * A configuração do eSocial.
   *
   * O ambiente, o mês de início e os códigos do empregador que vão no
   * S-1000 e no S-1005.
   *
   * `GET /v1/hr/esocial/settings`
   *
   * @param options Per-call overrides.
   */
  getEsocialSettings(options?: RequestOptions): Promise<S.HrEsocialSettings> {
    return this._http.request({ method: 'GET', path: `/v1/hr/esocial/settings`, options });
  }

  /**
   * A conferência das guias.
   *
   * Aceito o fechamento (S-1299), o governo devolve os totalizadores do
   * contribuinte: S-5011 (contribuições sociais), S-5012 (IRRF) e S-5013
   * (FGTS). Cada recolhimento mostra o apurado, o que a folha calculou e a
   * diferença. Com o período aberto, só a coluna da folha vem preenchida.
   *
   * `GET /v1/hr/esocial/settlements/{period}`
   *
   * @param period `AAAA-MM`, ou `AAAA` no 13º
   * @param options Per-call overrides.
   */
  getEsocialSettlement(period: string, options?: RequestOptions): Promise<S.HrEsocialSettlement> {
    return this._http.request({ method: 'GET', path: `/v1/hr/esocial/settlements/${seg(period)}`, options });
  }

  /**
   * Os lotes, do mais novo.
   *
   * Com o protocolo, a última resposta da Receita e a próxima tentativa.
   *
   * `GET /v1/hr/esocial/batches`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listEsocialBatches(query?: HrEsocialListEsocialBatchesQuery, options?: RequestOptions): Promise<S.HrEsocialBatchesPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/esocial/batches`, query, options });
  }

  /**
   * Iterates every item of `listEsocialBatches`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/esocial/batches`
   */
  listEsocialBatchesAll(query?: HrEsocialListEsocialBatchesQuery, options?: RequestOptions): Paginator<NonNullable<S.HrEsocialBatchesPage["items"]>[number], S.HrEsocialBatchesPage> {
    return new Paginator((page_token) => this.listEsocialBatches({ ...query, page_token } as HrEsocialListEsocialBatchesQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Os eventos, do mais novo.
   *
   * Com as mensagens de cada um: o que faltou no cadastro ou o que a Receita
   * devolveu. Sem o XML.
   *
   * `GET /v1/hr/esocial/events`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listEsocialEvents(query?: HrEsocialListEsocialEventsQuery, options?: RequestOptions): Promise<S.HrEsocialEventsPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/esocial/events`, query, options });
  }

  /**
   * Iterates every item of `listEsocialEvents`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/esocial/events`
   */
  listEsocialEventsAll(query?: HrEsocialListEsocialEventsQuery, options?: RequestOptions): Paginator<NonNullable<S.HrEsocialEventsPage["items"]>[number], S.HrEsocialEventsPage> {
    return new Paginator((page_token) => this.listEsocialEvents({ ...query, page_token } as HrEsocialListEsocialEventsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Grava a configuração do eSocial.
   *
   * Ligar exige o CNPJ do empregador na configuração da folha, a
   * classificação tributária, o CNAE, a lotação, o FPAS, terceiros e o mês
   * de início.
   *
   * `PUT /v1/hr/esocial/settings`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  putEsocialSettings(body: S.HrEsocialSettings, options?: RequestOptions): Promise<S.HrEsocialSettings> {
    return this._http.request({ method: 'PUT', path: `/v1/hr/esocial/settings`, body, options });
  }

  /**
   * Gera de novo.
   *
   * Depois de corrigir o cadastro: o evento inválido ou recusado ganha um
   * `Id` novo, o XML com os dados de agora e volta para a fila.
   *
   * `POST /v1/hr/esocial/events/{id}/regenerate`
   *
   * @param id Id do evento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  regenerateEsocialEvent(id: string, body: S.HrPayrollVersionInput, options?: RequestOptions): Promise<S.HrEsocialEvent> {
    return this._http.request({ method: 'POST', path: `/v1/hr/esocial/events/${seg(id)}/regenerate`, body, options });
  }
}

