/** Routes tagged `hr · recruitment`. */
export class HrRecruitmentResource extends Resource {
  /**
   * Cadastra um candidato na vaga.
   *
   * O candidato é uma pessoa do cadastro (`/v1/people`). Entra na primeira
   * etapa do funil, publica `hr.application.received` e ganha um cartão no
   * quadro; com o quadro fora, `card_placed` volta falso e o cartão chega em
   * seguida.
   *
   * `POST /v1/hr/openings/{id}/applications`
   *
   * @param id Id da vaga
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createApplication(id: string, body: S.HrApplicationInput, options?: RequestOptions): Promise<S.HrApplication> {
    return this._http.request({ method: 'POST', path: `/v1/hr/openings/${seg(id)}/applications`, body, options });
  }

  /**
   * Abre uma vaga para uma posição do quadro.
   *
   * Nasce aberta e publica `hr.opening.opened`. Uma posição tem no máximo uma
   * vaga viva: contratar mais gente para ela é aumentar as cadeiras.
   *
   * `POST /v1/hr/openings`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createJobOpening(body: S.HrJobOpeningInput, options?: RequestOptions): Promise<S.HrJobOpening> {
    return this._http.request({ method: 'POST', path: `/v1/hr/openings`, body, options });
  }

  /**
   * Uma candidatura.
   *
   * Com a vaga, a etapa, o motivo e a admissão, quando houve contratação.
   *
   * `GET /v1/hr/applications/{id}`
   *
   * @param id Id da candidatura
   * @param options Per-call overrides.
   */
  getApplication(id: string, options?: RequestOptions): Promise<S.HrApplication> {
    return this._http.request({ method: 'GET', path: `/v1/hr/applications/${seg(id)}`, options });
  }

  /**
   * Uma vaga.
   *
   * Em qualquer situação, da organização ativa (404 fora dela).
   *
   * `GET /v1/hr/openings/{id}`
   *
   * @param id Id da vaga
   * @param options Per-call overrides.
   */
  getJobOpening(id: string, options?: RequestOptions): Promise<S.HrJobOpening> {
    return this._http.request({ method: 'GET', path: `/v1/hr/openings/${seg(id)}`, options });
  }

  /**
   * As etapas e os motivos do recrutamento.
   *
   * O funil nasce com as etapas e os motivos padrão na primeira leitura. É o
   * mesmo desenho do quadro `hr.application` no módulo de Quadros: o id da
   * etapa é o id da coluna.
   *
   * `GET /v1/hr/recruitment/funnel`
   *
   * @param options Per-call overrides.
   */
  getRecruitmentFunnel(options?: RequestOptions): Promise<S.HrRecruitmentFunnel> {
    return this._http.request({ method: 'GET', path: `/v1/hr/recruitment/funnel`, options });
  }

  /**
   * Contrata o candidato.
   *
   * Abre a admissão em rascunho da pessoa na posição da vaga, move a
   * candidatura para a etapa de contratação e publica `hr.application.hired`.
   * Na última cadeira a vaga passa a `filled`. A admissão segue o caminho
   * normal em `/v1/hr/admissions/{id}`.
   *
   * `POST /v1/hr/applications/{id}/hire`
   *
   * @param id Id da candidatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  hireApplication(id: string, body: S.HrApplicationHireInput, options?: RequestOptions): Promise<S.HrHiredApplication> {
    return this._http.request({ method: 'POST', path: `/v1/hr/applications/${seg(id)}/hire`, body, options });
  }

  /**
   * O histórico de uma candidatura.
   *
   * Do mais novo para o mais antigo, com os movimentos recusados pelo quadro
   * e os feitos na tela dele (`from_board`).
   *
   * `GET /v1/hr/applications/{id}/moves`
   *
   * @param id Id da candidatura
   * @param options Per-call overrides.
   */
  listApplicationMoves(id: string, options?: RequestOptions): Promise<S.HrApplicationMoves> {
    return this._http.request({ method: 'GET', path: `/v1/hr/applications/${seg(id)}/moves`, options });
  }

  /**
   * As candidaturas de uma vaga.
   *
   * Da mais antiga para a mais nova, com o nome da pessoa e a etapa em que
   * cada uma está.
   *
   * `GET /v1/hr/openings/{id}/applications`
   *
   * @param id Id da vaga
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listApplications(id: string, query?: HrRecruitmentListApplicationsQuery, options?: RequestOptions): Promise<S.HrApplicationsPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/openings/${seg(id)}/applications`, query, options });
  }

  /**
   * Iterates every item of `listApplications`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/openings/{id}/applications`
   */
  listApplicationsAll(id: string, query?: HrRecruitmentListApplicationsQuery, options?: RequestOptions): Paginator<NonNullable<S.HrApplicationsPage["items"]>[number], S.HrApplicationsPage> {
    return new Paginator((page_token) => this.listApplications(id, { ...query, page_token } as HrRecruitmentListApplicationsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * As vagas da organização.
   *
   * Da mais nova para a mais antiga, com a contagem de candidaturas de cada
   * uma.
   *
   * `GET /v1/hr/openings`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listJobOpenings(query?: HrRecruitmentListJobOpeningsQuery, options?: RequestOptions): Promise<S.HrJobOpeningsPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/openings`, query, options });
  }

  /**
   * Iterates every item of `listJobOpenings`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/openings`
   */
  listJobOpeningsAll(query?: HrRecruitmentListJobOpeningsQuery, options?: RequestOptions): Paginator<NonNullable<S.HrJobOpeningsPage["items"]>[number], S.HrJobOpeningsPage> {
    return new Paginator((page_token) => this.listJobOpenings({ ...query, page_token } as HrRecruitmentListJobOpeningsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Move a candidatura de etapa.
   *
   * Para uma etapa em andamento, ou para a de quem não seguiu, com o motivo
   * (publica `hr.application.rejected`). Quem não seguiu pode voltar ao
   * processo. A etapa de contratação é só por `hire`.
   *
   * `POST /v1/hr/applications/{id}/move`
   *
   * @param id Id da candidatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  moveApplication(id: string, body: S.HrApplicationMoveInput, options?: RequestOptions): Promise<S.HrApplication> {
    return this._http.request({ method: 'POST', path: `/v1/hr/applications/${seg(id)}/move`, body, options });
  }

  /**
   * Pausa, retoma ou cancela uma vaga.
   *
   * Pausada não recebe candidato nem contrata. Cancelada e preenchida são
   * finais e liberam a posição para outra vaga; as candidaturas ficam como
   * estavam.
   *
   * `POST /v1/hr/openings/{id}/status`
   *
   * @param id Id da vaga
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setJobOpeningStatus(id: string, body: S.HrJobOpeningStatusInput, options?: RequestOptions): Promise<S.HrJobOpening> {
    return this._http.request({ method: 'POST', path: `/v1/hr/openings/${seg(id)}/status`, body, options });
  }

  /**
   * Altera origem, link e anotação.
   *
   * Manda o registro inteiro: campo ausente é gravado vazio. A pessoa e a vaga
   * não mudam. A etapa muda por `move` e `hire`.
   *
   * `PATCH /v1/hr/applications/{id}`
   *
   * @param id Id da candidatura
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateApplication(id: string, body: S.HrApplicationInput, options?: RequestOptions): Promise<S.HrApplication> {
    return this._http.request({ method: 'PATCH', path: `/v1/hr/applications/${seg(id)}`, body, options });
  }

  /**
   * Altera título, descrição, cadeiras e data.
   *
   * Manda o registro inteiro: campo ausente é gravado vazio. Só a vaga aberta
   * ou pausada. A posição não muda: vaga para outra posição é outra vaga.
   *
   * `PATCH /v1/hr/openings/{id}`
   *
   * @param id Id da vaga
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateJobOpening(id: string, body: S.HrJobOpeningInput, options?: RequestOptions): Promise<S.HrJobOpening> {
    return this._http.request({ method: 'PATCH', path: `/v1/hr/openings/${seg(id)}`, body, options });
  }

  /**
   * Redesenha as etapas e os motivos.
   *
   * Vem o funil inteiro, na ordem: renomeia, recolore, reordena, cria (id
   * vazio) e tira o que não vier. Só sai etapa vazia, sem candidatura nem
   * movimento à espera; a etapa de contratado é sempre a mesma e nenhuma etapa
   * troca de tipo, porque a situação de quem está nela mudaria por baixo. O
   * motivo que sai deixa de ser oferecido, e quem já o recebeu continua com
   * ele. O quadro do módulo de Quadros recebe o desenho novo na hora, ou na
   * próxima volta do laço quando não responde (`synced` falso até lá).
   *
   * `PUT /v1/hr/recruitment/funnel`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateRecruitmentFunnel(body: S.HrRecruitmentFunnelInput, options?: RequestOptions): Promise<S.HrRecruitmentFunnel> {
    return this._http.request({ method: 'PUT', path: `/v1/hr/recruitment/funnel`, body, options });
  }
}

