export interface HrTrainingsListTrainingPendingQuery {
  /** Só os vínculos desta unidade. */
  unit_id?: string;
  /** `expiring`, `expired` ou `missing`. Ausente = as três. */
  status?: string;
  /** Só este treinamento. */
  training_id?: string;
  /** Tamanho da página. Aparado pelo serviço. */
  page_size?: number;
  /** Cursor opaco da página anterior. */
  page_token?: string;
}

/** Query of `GET /v1/hr/trainings`. */
export interface HrTrainingsListTrainingsQuery {
  /** `active` ou `archived`. Ausente = todos. */
  status?: string;
  /** Trecho do nome. */
  q?: string;
  /** Tamanho da página. Aparado pelo serviço. */
  page_size?: number;
  /** Cursor opaco da página anterior. */
  page_token?: string;
}

/** Routes tagged `hr · trainings`. */
export class HrTrainingsResource extends Resource {
  /**
   * Cancela uma turma agendada.
   *
   * As inscrições da turma são canceladas junto. Não tem volta: para refazer,
   * abra outra turma.
   *
   * `POST /v1/hr/training-classes/{id}/cancel`
   *
   * @param id Id da turma
   * @param body Request body.
   * @param options Per-call overrides.
   */
  cancelTrainingClass(id: string, body: S.HrTrainingClassVersionInput, options?: RequestOptions): Promise<S.HrTrainingClass> {
    return this._http.request({ method: 'POST', path: `/v1/hr/training-classes/${seg(id)}/cancel`, body, options });
  }

  /**
   * Cancela uma inscrição.
   *
   * Libera a vaga, e a pessoa pode ser inscrita de novo na mesma turma.
   * Repetir o cancelamento devolve a inscrição como está.
   *
   * `POST /v1/hr/training-enrollments/{id}/cancel`
   *
   * @param id Id da inscrição
   * @param options Per-call overrides.
   */
  cancelTrainingEnrollment(id: string, options?: RequestOptions): Promise<S.HrTrainingEnrollment> {
    return this._http.request({ method: 'POST', path: `/v1/hr/training-enrollments/${seg(id)}/cancel`, options });
  }

  /**
   * Conclui a turma.
   *
   * Quem esteve presente ganha a conclusão no último dia da turma e, quando o
   * treinamento tem validade, o dia do vencimento. Publica um
   * `hr.training.completed` por pessoa presente.
   *
   * `POST /v1/hr/training-classes/{id}/complete`
   *
   * @param id Id da turma
   * @param body Request body.
   * @param options Per-call overrides.
   */
  completeTrainingClass(id: string, body: S.HrTrainingClassVersionInput, options?: RequestOptions): Promise<S.HrTrainingClass> {
    return this._http.request({ method: 'POST', path: `/v1/hr/training-classes/${seg(id)}/complete`, body, options });
  }

  /**
   * Cria um treinamento no catálogo.
   *
   * Nasce ativo. O nome é único na organização, sem diferença de maiúsculas e
   * contando os arquivados (409 se repetir).
   *
   * `POST /v1/hr/trainings`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createTraining(body: S.HrTrainingInput, options?: RequestOptions): Promise<S.HrTraining> {
    return this._http.request({ method: 'POST', path: `/v1/hr/trainings`, body, options });
  }

  /**
   * Abre uma turma de um treinamento ativo.
   *
   * Nasce agendada. O fim não vem antes do início e a turma dura até 366 dias.
   *
   * `POST /v1/hr/training-classes`
   *
   * @param body Request body.
   * @param options Per-call overrides.
   */
  createTrainingClass(body: S.HrTrainingClassInput, options?: RequestOptions): Promise<S.HrTrainingClass> {
    return this._http.request({ method: 'POST', path: `/v1/hr/training-classes`, body, options });
  }

  /**
   * Baixa o certificado.
   *
   * Quem autoriza é o RH: a leitura de treinamento no alcance do vínculo, ou o
   * portal para a própria inscrição. Os bytes saem em fluxo, pelo mesmo laço
   * do download do cofre.
   *
   * `GET /v1/hr/training-enrollments/{id}/certificate`
   *
   * @param id Id da inscrição
   * @param options Per-call overrides.
   */
  downloadTrainingCertificate(id: string, options?: RequestOptions): Promise<Response> {
    return this._http.request({ method: 'GET', path: `/v1/hr/training-enrollments/${seg(id)}/certificate`, responseType: 'raw', options });
  }

  /**
   * Inscreve uma pessoa.
   *
   * O vínculo precisa estar ativo ou afastado. O gestor inscreve quem é da
   * equipe; o RH, qualquer um. Publica `hr.training.enrolled`.
   *
   * `POST /v1/hr/training-classes/{id}/enrollments`
   *
   * @param id Id da turma
   * @param body Request body.
   * @param options Per-call overrides.
   */
  enrollInTraining(id: string, body: S.HrTrainingEnrollInput, options?: RequestOptions): Promise<S.HrTrainingEnrollment> {
    return this._http.request({ method: 'POST', path: `/v1/hr/training-classes/${seg(id)}/enrollments`, body, options });
  }

  /**
   * Os treinamentos de um vínculo.
   *
   * Os obrigatórios do cargo atual, cada um com a situação pela conclusão mais
   * nova (`ok`, `expiring`, `expired` ou `missing`), e as inscrições da pessoa.
   *
   * `GET /v1/hr/employments/{id}/trainings`
   *
   * @param id Id do vínculo
   * @param options Per-call overrides.
   */
  getEmploymentTrainings(id: string, options?: RequestOptions): Promise<S.HrEmploymentTrainings> {
    return this._http.request({ method: 'GET', path: `/v1/hr/employments/${seg(id)}/trainings`, options });
  }

  /**
   * Os treinamentos obrigatórios de um cargo.
   *
   * Na ordem gravada. O arquivado que o cargo já exigia aparece com a situação
   * `archived` e não entra na conta das pendências.
   *
   * `GET /v1/hr/jobs/{id}/trainings`
   *
   * @param id Id do cargo
   * @param options Per-call overrides.
   */
  getJobTrainings(id: string, options?: RequestOptions): Promise<S.HrJobTrainings> {
    return this._http.request({ method: 'GET', path: `/v1/hr/jobs/${seg(id)}/trainings`, options });
  }

  /**
   * Um treinamento.
   *
   * Ativo ou arquivado, da organização ativa (404 fora dela).
   *
   * `GET /v1/hr/trainings/{id}`
   *
   * @param id Id do treinamento
   * @param options Per-call overrides.
   */
  getTraining(id: string, options?: RequestOptions): Promise<S.HrTraining> {
    return this._http.request({ method: 'GET', path: `/v1/hr/trainings/${seg(id)}`, options });
  }

  /**
   * Uma turma.
   *
   * Com o treinamento e as contagens. As pessoas saem em
   * `GET /v1/hr/training-classes/{id}/enrollments`.
   *
   * `GET /v1/hr/training-classes/{id}`
   *
   * @param id Id da turma
   * @param options Per-call overrides.
   */
  getTrainingClass(id: string, options?: RequestOptions): Promise<S.HrTrainingClass> {
    return this._http.request({ method: 'GET', path: `/v1/hr/training-classes/${seg(id)}`, options });
  }

  /**
   * As turmas da organização.
   *
   * Da mais nova para a mais antiga, com as contagens de inscritos, presentes
   * e de quem ainda está sem presença lançada.
   *
   * `GET /v1/hr/training-classes`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listTrainingClasses(query?: HrTrainingsListTrainingClassesQuery, options?: RequestOptions): Promise<S.HrTrainingClassesPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/training-classes`, query, options });
  }

  /**
   * Iterates every item of `listTrainingClasses`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/training-classes`
   */
  listTrainingClassesAll(query?: HrTrainingsListTrainingClassesQuery, options?: RequestOptions): Paginator<NonNullable<S.HrTrainingClassesPage["items"]>[number], S.HrTrainingClassesPage> {
    return new Paginator((page_token) => this.listTrainingClasses({ ...query, page_token } as HrTrainingsListTrainingClassesQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * As pessoas da turma.
   *
   * O RH vê todas; o gestor vê as da equipe. As canceladas também saem, com a
   * situação `cancelled`.
   *
   * `GET /v1/hr/training-classes/{id}/enrollments`
   *
   * @param id Id da turma
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listTrainingEnrollments(id: string, query?: HrTrainingsListTrainingEnrollmentsQuery, options?: RequestOptions): Promise<S.HrTrainingEnrollmentsPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/training-classes/${seg(id)}/enrollments`, query, options });
  }

  /**
   * Iterates every item of `listTrainingEnrollments`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/training-classes/{id}/enrollments`
   */
  listTrainingEnrollmentsAll(id: string, query?: HrTrainingsListTrainingEnrollmentsQuery, options?: RequestOptions): Paginator<NonNullable<S.HrTrainingEnrollmentsPage["items"]>[number], S.HrTrainingEnrollmentsPage> {
    return new Paginator((page_token) => this.listTrainingEnrollments(id, { ...query, page_token } as HrTrainingsListTrainingEnrollmentsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Os obrigatórios que não estão em dia.
   *
   * Uma linha por vínculo ativo e treinamento obrigatório do cargo que nunca
   * foi concluído, venceu ou vence em até 30 dias, no alcance de quem pede.
   *
   * `GET /v1/hr/training-pending`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listTrainingPending(query?: HrTrainingsListTrainingPendingQuery, options?: RequestOptions): Promise<S.HrPendingTrainingsPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/training-pending`, query, options });
  }

  /**
   * Iterates every item of `listTrainingPending`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/training-pending`
   */
  listTrainingPendingAll(query?: HrTrainingsListTrainingPendingQuery, options?: RequestOptions): Paginator<NonNullable<S.HrPendingTrainingsPage["items"]>[number], S.HrPendingTrainingsPage> {
    return new Paginator((page_token) => this.listTrainingPending({ ...query, page_token } as HrTrainingsListTrainingPendingQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * O catálogo de treinamentos da organização.
   *
   * Cada item diz quantos cargos o exigem e quantas turmas não canceladas tem.
   *
   * `GET /v1/hr/trainings`
   *
   * @param query Query string parameters.
   * @param options Per-call overrides.
   */
  listTrainings(query?: HrTrainingsListTrainingsQuery, options?: RequestOptions): Promise<S.HrTrainingsPage> {
    return this._http.request({ method: 'GET', path: `/v1/hr/trainings`, query, options });
  }

  /**
   * Iterates every item of `listTrainings`, following `next_page_token` page after page.
   *
   * `GET /v1/hr/trainings`
   */
  listTrainingsAll(query?: HrTrainingsListTrainingsQuery, options?: RequestOptions): Paginator<NonNullable<S.HrTrainingsPage["items"]>[number], S.HrTrainingsPage> {
    return new Paginator((page_token) => this.listTrainings({ ...query, page_token } as HrTrainingsListTrainingsQuery, options), "items", query?.page_token ?? undefined);
  }

  /**
   * Troca a lista de obrigatórios do cargo.
   *
   * A lista vem inteira, na ordem; vazia tira todos. Só entra treinamento
   * ativo da organização (o arquivado que o cargo já exigia pode ficar).
   *
   * `PUT /v1/hr/jobs/{id}/trainings`
   *
   * @param id Id do cargo
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setJobTrainings(id: string, body: S.HrJobTrainingsInput, options?: RequestOptions): Promise<S.HrJobTrainings> {
    return this._http.request({ method: 'PUT', path: `/v1/hr/jobs/${seg(id)}/trainings`, body, options });
  }

  /**
   * Lança a presença.
   *
   * Presente ou ausente, uma pessoa por vez, e pode ser corrigida enquanto a
   * turma está agendada. A conclusão só é gravada ao concluir a turma.
   *
   * `POST /v1/hr/training-enrollments/{id}/attendance`
   *
   * @param id Id da inscrição
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setTrainingAttendance(id: string, body: S.HrTrainingAttendanceInput, options?: RequestOptions): Promise<S.HrTrainingEnrollment> {
    return this._http.request({ method: 'POST', path: `/v1/hr/training-enrollments/${seg(id)}/attendance`, body, options });
  }

  /**
   * Anexa o certificado.
   *
   * O arquivo sobe antes pelo Files (`POST /v1/files`). Aqui o RH o adota: lê
   * com a sessão de quem anexa e guarda uma cópia que só ele abre, presa ao
   * vínculo. Anexar de novo troca o certificado.
   *
   * `PUT /v1/hr/training-enrollments/{id}/certificate`
   *
   * @param id Id da inscrição
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setTrainingCertificate(id: string, body: S.HrTrainingCertificateInput, options?: RequestOptions): Promise<S.HrTrainingEnrollment> {
    return this._http.request({ method: 'PUT', path: `/v1/hr/training-enrollments/${seg(id)}/certificate`, body, options });
  }

  /**
   * Arquiva ou reativa um treinamento.
   *
   * Arquivado some das escolhas, não abre turma nova e sai da conta dos
   * obrigatórios; as turmas e as conclusões que já existem continuam.
   *
   * `POST /v1/hr/trainings/{id}/status`
   *
   * @param id Id do treinamento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  setTrainingStatus(id: string, body: S.HrTrainingStatusInput, options?: RequestOptions): Promise<S.HrTraining> {
    return this._http.request({ method: 'POST', path: `/v1/hr/trainings/${seg(id)}/status`, body, options });
  }

  /**
   * Altera o treinamento.
   *
   * Manda o registro inteiro: campo ausente é gravado vazio. Mudar a validade
   * só vale para as turmas concluídas depois: o que já foi concluído mantém o
   * vencimento que ganhou.
   *
   * `PATCH /v1/hr/trainings/{id}`
   *
   * @param id Id do treinamento
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateTraining(id: string, body: S.HrTrainingInput, options?: RequestOptions): Promise<S.HrTraining> {
    return this._http.request({ method: 'PATCH', path: `/v1/hr/trainings/${seg(id)}`, body, options });
  }

  /**
   * Altera uma turma agendada.
   *
   * Instrutor, local, datas e vagas. Manda o registro inteiro: campo ausente é
   * gravado vazio. O treinamento da turma não muda.
   *
   * `PATCH /v1/hr/training-classes/{id}`
   *
   * @param id Id da turma
   * @param body Request body.
   * @param options Per-call overrides.
   */
  updateTrainingClass(id: string, body: S.HrTrainingClassInput, options?: RequestOptions): Promise<S.HrTrainingClass> {
    return this._http.request({ method: 'PATCH', path: `/v1/hr/training-classes/${seg(id)}`, body, options });
  }
}

/** Routes tagged `hr`. */
export class HrResource extends Resource {
  readonly admissions = new HrAdmissionsResource(this._http);
  readonly benefits = new HrBenefitsResource(this._http);
  readonly climate = new HrClimateResource(this._http);
  readonly competencies = new HrCompetenciesResource(this._http);
  readonly dashboard = new HrDashboardResource(this._http);
  readonly documents = new HrDocumentsResource(this._http);
  readonly employments = new HrEmploymentsResource(this._http);
  readonly esocial = new HrEsocialResource(this._http);
  readonly indicators = new HrIndicatorsResource(this._http);
  readonly jobs = new HrJobsResource(this._http);
  readonly leave = new HrLeaveResource(this._http);
  readonly movements = new HrMovementsResource(this._http);
  readonly occupationalExams = new HrOccupationalExamsResource(this._http);
  readonly payroll = new HrPayrollResource(this._http);
  readonly performance = new HrPerformanceResource(this._http);
  readonly portal = new HrPortalResource(this._http);
  readonly positions = new HrPositionsResource(this._http);
  readonly recruitment = new HrRecruitmentResource(this._http);
  readonly reviews = new HrReviewsResource(this._http);
  readonly schedules = new HrSchedulesResource(this._http);
  readonly settings = new HrSettingsResource(this._http);
  readonly signatures = new HrSignaturesResource(this._http);
  readonly sst = new HrSstResource(this._http);
  readonly terminations = new HrTerminationsResource(this._http);
  readonly time = new HrTimeResource(this._http);
  readonly trainings = new HrTrainingsResource(this._http);
}
